#!/usr/bin/env python3
"""Reusable helpers for driving the create/edit journal dialog."""
import sys, os, time
sys.path.insert(0, "/workspace/explore")
from tj import Tj


def dlg(t, label):
    print(f"----- {label} -----")
    lines = t.cap().splitlines()
    out = []; grab = False
    for l in lines:
        if "Create journal" in l or "Edit journal" in l:
            grab = True
        if grab:
            out.append(l)
        if grab and "Open tags" in l:
            break
    print("\n".join(out) if out else "\n".join(lines))
    print(f"----- /{label} -----")


def cap(t, label):
    print(f"----- {label} -----")
    print(t.cap())
    print(f"----- /{label} -----")


def create(t, title, date=None, priority=None, tags=None, confirm=True, show=None):
    """date as 'DD-MM-YYYY' string; priority/tags as strings."""
    t.send("n", 0.6)
    if title:
        t.send(title, 0.3)
    t.send("^Tab", 0.25)
    if date is not None:
        for _ in range(12):
            t.send("^Delete", 0.02)
        time.sleep(0.2)
        t.send(date, 0.25)
    t.send("^Tab", 0.25)
    if priority is not None:
        t.send(priority, 0.25)
    t.send("^Tab", 0.25)
    if tags is not None:
        t.send(tags, 0.25)
    if show:
        dlg(t, show)
    if confirm:
        t.send("^Enter", 0.8)


def set_content(t, text_lines):
    """Enter the content editor, type lines, save with ^C-s, then Escape."""
    t.send("^Enter", 0.5)     # start editing content
    t.send("i", 0.3)          # insert mode (vim-like editor)
    for i, ln in enumerate(text_lines):
        if i:
            t.send("^Enter", 0.15)
        t.send(ln, 0.15)
    time.sleep(0.2)
    t.send("^Escape", 0.3)
    t.send("^C-s", 0.6)
